import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('exportCsv with empty invoices returns header only', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], '');
  assert.equal(lines.length, 2);
});

test('exportCsv returns header line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv includes invoice number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert.ok(lines[1].startsWith(issued.value.number + ','));
});

test('exportCsv includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes('Acme Corporation'));
});

test('exportCsv includes issueDate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes('2026-10-07'));
});

test('exportCsv includes dueDate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes(issued.value.dueDate));
});

test('exportCsv includes status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes('issued'));
});

test('exportCsv formats amounts as euros with 2 decimals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(/\d+\.\d{2}/.test(result));
  assert.ok(!result.includes('€'));
  assert.ok(!result.includes('cent'));
});

test('exportCsv includes subtotal', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const expectedSubtotal = (totals.subtotal / 100).toFixed(2);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes(expectedSubtotal));
});

test('exportCsv includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const expectedDiscount = (totals.discount / 100).toFixed(2);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes(expectedDiscount));
});

test('exportCsv includes vat', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const expectedVat = (totals.vat / 100).toFixed(2);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes(expectedVat));
});

test('exportCsv includes total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const expectedTotal = (totals.total / 100).toFixed(2);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes(expectedTotal));
});

test('exportCsv includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const due = balanceDue(issued.value);
  const expectedDue = (due / 100).toFixed(2);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes(expectedDue));
});

test('exportCsv includes due 0 for paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-15' });

  const result = exportCsv([paid.value]);
  assert.ok(result.includes('0.00'));
});

test('exportCsv ends lines with newline', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.endsWith('\n'));
});

test('exportCsv separates lines with newline', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert.ok(lines[0].length > 0);
  assert.ok(lines[1].length > 0);
  assert.equal(lines[2], '');
});

test('exportCsv handles multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, ['INV-2026-0001']);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = exportCsv([issued1.value, issued2.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert.ok(lines[1].includes(issued1.value.number));
  assert.ok(lines[2].includes(issued2.value.number));
});

test('exportCsv preserves invoice order', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, ['INV-2026-0001']);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = exportCsv([issued2.value, issued1.value]);
  const lines = result.split('\n');

  assert.ok(lines[1].includes(issued2.value.number));
  assert.ok(lines[2].includes(issued1.value.number));
});

test('exportCsv escapes field with comma', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes('"'));
});

test('exportCsv escapes field with double quote', () => {
  const r = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = exportCsv([issued.value]);
  assert.ok(result.includes('""'));
});

test('exportCsv correctly formats all amounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',').filter(f => !f.startsWith('"'));
  const amountFields = fields.slice(5);

  amountFields.forEach((field) => {
    assert.ok(/^\d+\.\d{2}$/.test(field));
  });
});

test('exportCsv handles partially paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const partial = recordPayment(issued.value, { amount: 20000, date: '2026-10-15' });
  const due = balanceDue(partial.value);
  const expectedDue = (due / 100).toFixed(2);

  const result = exportCsv([partial.value]);
  assert.ok(result.includes(expectedDue));
  assert.ok(result.includes('partially_paid'));
});

